import React from 'react';
import './ResumePreview.css';

/**
 * Component for rendering a preview of the uploaded resume.
 */
const ResumePreview = ({ analysisData }) => {
  return (
    <div className="resume-preview">
      <h2>Resume Preview</h2>
      {analysisData ? (
        <div>
          <p><strong>File:</strong> {analysisData.originalName || analysisData.filename}</p>
          <p><strong>Status:</strong> {analysisData.status}</p>
          {analysisData.extractedText && (
            <pre className="resume-preview__text">{analysisData.extractedText}</pre>
          )}
        </div>
      ) : (
        <p>The uploaded document preview will appear here after implementation.</p>
      )}
    </div>
  );
};

export default ResumePreview;
